import { describe, expect, it } from "vitest";
import { encodeQr, qrPath } from "@/lib/qr/encoder";
import { createQrMatrix } from "@/lib/qr/qr-code";

/**
 * The expected matrix below was generated by encoder.ts and decoded back to the same text
 * with OpenCV (QRCodeDetector and QRCodeDetectorAruco), together with 88 other codes
 * covering versions 2–20 and all four error-correction levels. The previous generator's
 * output could not be decoded at all.
 */
const AISHA_M = [
    "#######..##.#.#...##..#######",
    "#.....#.####.#...#.##.#.....#",
    "#.###.#..###...#...#..#.###.#",
    "#.###.#...#..#..#.#...#.###.#",
    "#.###.#.#...##..#####.#.###.#",
    "#.....#..####.####.#..#.....#",
    "#######.#.#.#.#.#.#.#.#######",
    ".........#..#..#.###.........",
    "#.#.#.#....##...##......#..#.",
    "#..#...#..#.##.####.###..#..#",
    "#..##.####..#.#####.#.###.###",
    "#.#.#..#.#.####.####..###..#.",
    "##...##...#...##.#...##..#.##",
    ".#.#.#..#...#.##....###..#..#",
    "#...###.#..###....#...##.#.##",
    ".###......#.#..#.#.#.....#.#.",
    "##.#.####.##....##..###..#.##",
    "..#.#....#..##.###..#.#..##.#",
    "#..####....#..###.#.#.###..##",
    ".#..##.....####.###.######.#.",
    "#.##.##.#.###.##..#######....",
    "........#...#.##...##...#.###",
    "#######......#...#.##.#.##.##",
    "#.....#..#..#..#...##...##..#",
    "#.###.#.#.###...#...#####....",
    "#.###.#..#..#..###..#..##.#..",
    "#.###.#.#...#..##.##...###..#",
    "#.....#..#..###.#####..#...#.",
    "#######.#.######..###.###..##",
];

const toRows = (m: boolean[][]) => m.map((r) => r.map((c) => (c ? "#" : ".")).join(""));

describe("QR encoder", () => {
  it("matches the decoder-verified matrix for a card URL", () => {
    expect(toRows(encodeQr("https://digicardo.app/aisha", "M"))).toEqual(AISHA_M);
  });

  it("picks the smallest version that fits", () => {
    expect(encodeQr("hi", "M")).toHaveLength(21); // version 1
    expect(encodeQr("https://digicardo.app/" + "x".repeat(60), "M")).toHaveLength(37); // version 5
    expect(encodeQr("x".repeat(300), "L").length).toBeGreaterThan(57);
  });

  it("draws the three finder patterns", () => {
    const m = encodeQr("https://digicardo.app/rohan", "Q");
    const n = m.length;
    for (const [r, c] of [[0, 0], [0, n - 7], [n - 7, 0]]) {
      expect(toRows(m.slice(r, r + 7).map((row) => row.slice(c, c + 7)))).toEqual([
        "#######", "#.....#", "#.###.#", "#.###.#", "#.###.#", "#.....#", "#######",
      ]);
    }
  });

  it("encodes UTF-8 text and rejects text that cannot fit", () => {
    expect(() => encodeQr("café ☕", "H")).not.toThrow();
    expect(() => encodeQr("x".repeat(3000), "H")).toThrow(RangeError);
  });

  it("produces SVG path data and is used by the legacy helper", () => {
    const m = encodeQr("a", "L");
    expect(qrPath(m)).toMatch(/^M0 0h1v1h-1z/);
    expect(toRows(createQrMatrix("https://digicardo.app/aisha"))).toEqual(AISHA_M);
  });
});
